task.setup:
const courses = [
    { id: "html", title: "HTML", lessons: 10, isNew: false },
    { id: "css", title: "CSS", lessons: 10, isNew: false },
    { id: "js", title: "JavaScript", lessons: 10, isNew: true },
];

task.solution:
function renderCourses(list) {
    const container = document.querySelector("#course-list");
    const count = document.querySelector("#course-count");

    container.textContent = "";

    for (const course of list) {
        const item = document.createElement("li");
        item.classList.add("course");
        item.textContent = `${course.title} - ${course.lessons} уроков`;
        item.dataset.id = course.id;

        if (course.isNew) {
            item.classList.add("course--new");
        }

        container.append(item);
    }

    count.textContent = `Курсов: ${list.length}`;
}

renderCourses(courses);

